use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance, ItemVerdict};

struct Node;

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_heading(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "Must read",
        Importance::WorthALook => "Worth a look",
        Importance::Skip => "Also seen",
    }
}

fn push_entry(out: &mut String, e: &ItemVerdict) {
    out.push_str("- [");
    out.push_str(category_label(e.category));
    out.push_str("] ");
    let title = e.title.trim();
    if title.is_empty() {
        out.push_str("(untitled)");
    } else {
        out.push_str(title);
    }
    out.push('\n');
    let link = e.link.trim();
    if !link.is_empty() {
        out.push_str("  ");
        out.push_str(link);
        out.push('\n');
    }
    let summary = e.summary.trim();
    if !summary.is_empty() {
        out.push_str("  ");
        out.push_str(summary);
        out.push('\n');
    }
}

fn render(composed: &Digest) -> String {
    let mut out = String::new();
    out.push_str("Digest for ");
    out.push_str(composed.date.trim());
    out.push('\n');

    let overview = composed.overview.trim();
    if !overview.is_empty() {
        out.push('\n');
        out.push_str(overview);
        out.push('\n');
    }

    let mut any = false;
    for level in [
        Importance::MustRead,
        Importance::WorthALook,
        Importance::Skip,
    ] {
        let mut headed = false;
        for e in composed
            .entries
            .iter()
            .filter(|e| e.kept && e.importance == level)
        {
            if !headed {
                out.push('\n');
                out.push_str(importance_heading(level));
                out.push_str(":\n");
                headed = true;
            }
            push_entry(&mut out, e);
            any = true;
        }
    }

    if !any {
        out.push_str("\nNo items made the digest this run.\n");
    }

    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);
        // Report honestly whether the channel accepted the notification.
        let published = notifier::notify(&message);
        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
